package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PersistentFinanceTransactionService{private final LedgerRepository ledgers;private final AccountRepository accounts;private final FinanceTransactionRepository transactions;public PersistentFinanceTransactionService(LedgerRepository l,AccountRepository a,FinanceTransactionRepository t){ledgers=l;accounts=a;transactions=t;}public Mono<TransactionView> create(UUID actor,UUID ledgerId,CreateTransactionRequest q){if(q.amount().signum()<=0)return Mono.error(new IllegalArgumentException("交易金额必须大于 0"));if(q.type()==TransactionType.TRANSFER&&(q.targetAccountId()==null||q.targetAccountId().equals(q.accountId())))return Mono.error(new IllegalArgumentException("Transfer 必须指定不同的目标账户"));return ledger(actor,ledgerId).flatMap(l->account(actor,ledgerId,q.accountId()).flatMap(source->(q.type()==TransactionType.TRANSFER?account(actor,ledgerId,q.targetAccountId()).map(target->new AccountPair(source,target)):Mono.just(new AccountPair(source,null))).flatMap(pair->{String currency=q.currency()==null?pair.source.currency():q.currency().toUpperCase();Instant n=Instant.now();FinanceTransactionEntity tx=new FinanceTransactionEntity(null,ledgerId,actor,q.type(),q.accountId(),q.targetAccountId(),q.amount(),currency,q.categoryId(),q.payee(),q.note(),q.occurredAt(),TransactionStatus.POSTED,q.source(),n,null);return transactions.save(tx).flatMap(saved->updateBalances(pair,q).thenReturn(saved));}))).map(this::view);}public Flux<TransactionView> list(UUID actor,UUID ledgerId){return ledger(actor,ledgerId).flatMapMany(l->transactions.findAllByLedgerIdAndOwnerIdOrderByOccurredAtDesc(ledgerId,actor).map(this::view));}public Flux<TransactionView> month(UUID actor,UUID ledgerId,Instant from,Instant to){return ledger(actor,ledgerId).flatMapMany(l->transactions.findAllByLedgerIdAndOwnerIdAndOccurredAtGreaterThanEqualAndOccurredAtLessThanOrderByOccurredAtDesc(ledgerId,actor,from,to).map(this::view));}private Mono<Void> updateBalances(AccountPair p,CreateTransactionRequest q){BigDecimal amount=q.amount();if(q.type()==TransactionType.INCOME)return save(p.source,p.source.currentBalance().add(amount));if(q.type()==TransactionType.EXPENSE)return save(p.source,p.source.currentBalance().subtract(amount));if(q.type()==TransactionType.TRANSFER)return save(p.source,p.source.currentBalance().subtract(amount)).then(save(p.target,p.target.currentBalance().add(amount)));return save(p.source,p.source.currentBalance().add(amount));}private Mono<Void> save(AccountEntity x,BigDecimal balance){return accounts.save(new AccountEntity(x.id(),x.ledgerId(),x.ownerId(),x.name(),x.type(),x.currency(),x.openingBalance(),balance,x.institution(),x.maskedIdentifier(),x.credentialRef(),x.archived(),x.createdAt(),Instant.now(),x.version())).then();}private Mono<LedgerEntity> ledger(UUID a,UUID id){return ledgers.findById(id).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private Mono<AccountEntity> account(UUID a,UUID l,UUID id){return accounts.findById(id).filter(x->x.ownerId().equals(a)&&x.ledgerId().equals(l)).switchIfEmpty(Mono.error(new NotFoundException("Account 不存在或不属于该 Ledger")));}private TransactionView view(FinanceTransactionEntity x){return new TransactionView(x.id(),x.ledgerId(),x.type(),x.accountId(),x.targetAccountId(),x.amount(),x.currency(),x.categoryId(),x.payee(),x.note(),x.occurredAt(),x.status(),x.source());}private record AccountPair(AccountEntity source,AccountEntity target) {}}
